// This file is generated by AI.

// 项目根目录的**单一**递归监听。
//
// 需要"项目里有文件变了"的地方不止一处 (git 状态刷新、磁盘变更同步; 语言服务另有一套按路径
// 合并转发的实现, 见 `lsp/watch.ts`)。各自 `watch` 同一个根的话, 同一次系统回调会被派发三遍,
// 而且每一份都要自己处理 `.git/` 自激与路径归一化。这里把"监听项目文件"收成一条事件源。
//
// ⚠️ 只负责派发, **不做防抖、不做合并**: 各订阅者的口径不同 (git 状态 400ms 足够, 磁盘同步
// 希望尽快), 放在这里会让它们互相牵制。防抖请在自己的回调里做。
//
// ⚠️ `.git/` 等版本控制元数据一律跳过, 判据见 `lib/watch-filter.ts`: `git status` 自己会写
// 索引锁, 不跳过就是"git status -> 写索引 -> 触发监听 -> git status"的自激回路。

import { watch, type UnwatchFn } from '@tauri-apps/plugin-fs';

import { hasRelevantWatchPath } from './watch-filter';

export type ProjectWatchListener = (paths: string[]) => void;

const listeners = new Set<ProjectWatchListener>();

let unwatch: UnwatchFn | null = null;
let activeRoot: string | null = null;

/**
 * 订阅"项目里有文件变了"。返回退订函数 —— 组件/模块的生命周期结束时必须调用。
 *
 * 事件路径已归一化 (见 `normalizeWatchPath`); 事件**没带路径**时回调收到空数组, 表示"不知道
 * 具体变了什么", 订阅者应当按"可能全都变了"处理。
 */
export function onProjectFilesChanged(listener: ProjectWatchListener): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/** 某次监听是否正在运行 (给"我需不需要自己起一条"这类判断用)。 */
export function projectWatchActive(): boolean {
  return unwatch !== null;
}

/**
 * 开始监听项目根 (递归)。同一个根的重复调用是幂等的; 换根会先拆掉旧的。
 *
 * 失败只记日志、不抛: 文件监听是"更好用", 不是功能本身的前提 —— 监听起不来时磁盘变更同步
 * 仍会被窗口聚焦与显式的还原/切分支动作触发。
 */
export async function startProjectWatch(root: string): Promise<void> {
  if (activeRoot === root && unwatch) return;
  stopWatcher();
  activeRoot = root;
  try {
    unwatch = await watch(
      [root],
      (event) => {
        dispatch(event.paths);
      },
      { recursive: true, delayMs: 200 }
    );
  } catch (error) {
    console.error('文件监听启动失败', error);
    unwatch = null;
    activeRoot = null;
  }
}

/** 停止监听 (订阅者保留, 之后再 `startProjectWatch` 仍然生效)。 */
export function stopProjectWatch(): void {
  stopWatcher();
  activeRoot = null;
}

function stopWatcher(): void {
  if (!unwatch) return;
  unwatch();
  unwatch = null;
}

function dispatch(paths: readonly string[] | undefined): void {
  if (!hasRelevantWatchPath(paths)) return;
  const changed = (paths ?? []).map(normalizeWatchPath).filter((path): path is string => path !== null);
  for (const listener of listeners) {
    try {
      listener(changed);
    } catch (error) {
      // 一个订阅者出错不该让其余订阅者也收不到事件
      console.error('文件变更订阅者失败', error);
    }
  }
}

/**
 * 归一化事件路径: 去掉 `file://` 与 Windows 的 `\\?\` 前缀, 反斜杠转正斜杠。
 *
 * 只做这些 —— 大小写与"是不是同一个路径"由订阅者自己按需要处理 (`editor/disk-state.ts` 的
 * `pathKey` 就是为此存在): 这里再折一次大小写, 传给 Tauri / 语言服务的原始路径就没了。
 */
export function normalizeWatchPath(raw: string): string | null {
  let path = raw;
  if (path.startsWith('file://')) path = path.slice('file://'.length);
  if (path.startsWith('\\\\?\\')) path = path.slice(4);
  path = path.replace(/\\/g, '/');
  return path || null;
}
